// Generated from src/registry/sources/control-ui/recipes/transcript-divider.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const transcriptDividerKnobs = [
  "--cui-transcript-divider-foreground",
  "--cui-transcript-divider-line-color",
  "--cui-transcript-divider-danger-foreground",
  "--cui-transcript-divider-success-foreground",
  "--cui-transcript-divider-warning-foreground",
] as const;
export type TranscriptDividerKnobStyle = Partial<Record<(typeof transcriptDividerKnobs)[number], string>>;

@layer components {
  :where([data-control-family="transcript-divider"][data-slot="root"]) {
    --cui-transcript-divider-foreground: var(--muted-foreground);
    --cui-transcript-divider-line-color: var(--border);
    --cui-transcript-divider-danger-foreground: var(--destructive-text);
    --cui-transcript-divider-success-foreground: var(--badge-green-foreground);
    --cui-transcript-divider-warning-foreground: var(--badge-yellow-foreground);
    margin-block: calc(var(--spacing) * 2);
    color: var(--cui-transcript-divider-foreground);
    font-size: var(--text-caption);
  }

  :where([data-control-family="transcript-divider"][data-slot="root"])::before,
  :where([data-control-family="transcript-divider"][data-slot="root"])::after {
    block-size: 1px;
    background: var(--cui-transcript-divider-line-color);
  }

  :where([data-control-family="transcript-divider"][data-slot="label"]) {
    padding-inline: calc(var(--spacing) * 2);
  }

  :where([data-control-family="transcript-divider"][data-slot="root"][data-tone="success"]) {
    color: var(--cui-transcript-divider-success-foreground);
  }

  :where([data-control-family="transcript-divider"][data-slot="root"][data-tone="warning"]) {
    color: var(--cui-transcript-divider-warning-foreground);
  }

  :where([data-control-family="transcript-divider"][data-slot="root"][data-tone="danger"]) {
    color: var(--cui-transcript-divider-danger-foreground);
  }
}

@property --cui-transcript-divider-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-transcript-divider-line-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-transcript-divider-danger-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-transcript-divider-success-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-transcript-divider-warning-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

import type { ComponentProps, CSSProperties } from "react";
import type { TranscriptDividerKnobStyle } from "@/components/control-ui/knob-contracts/transcript-divider-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type ChatTone = "neutral" | "success" | "warning" | "danger";

export type TranscriptDividerProps = Omit<ComponentProps<"div">, "style"> & {
  tone?: ChatTone;
  style?: CSSProperties & TranscriptDividerKnobStyle;
};

export function TranscriptDivider({ tone = "neutral", className, children, ...props }: TranscriptDividerProps) {
  return (
    <div
      data-control-ui="transcript-divider"
      data-control-family="transcript-divider"
      data-slot="root"
      data-tone={tone}
      className={cn("flex min-w-0 items-center before:flex-1 after:flex-1", className)}
      {...props}
    >
      {children != null ? <TranscriptDividerLabel>{children}</TranscriptDividerLabel> : null}
    </div>
  );
}

export type TranscriptDividerLabelProps = ComponentProps<"span"> & { style?: CSSProperties & TranscriptDividerKnobStyle };

export function TranscriptDividerLabel({ className, ...props }: TranscriptDividerLabelProps) {
  return (
    <span
      data-control-ui="transcript-divider"
      data-control-family="transcript-divider"
      data-slot="label"
      className={cn("min-w-0 truncate", className)}
      {...props}
    />
  );
}
